'use client';
import { useEffect, useRef, useState, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect, useReducedMotion } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { enter, Spin, Swap, Tip } from '../lib/motion';
import { usePopover } from '../lib/popover';
import '../designme.css';
// its menus' rows glide in Clean
import '../lib/glide';
import './permission-gate.css';

/** Something the agent is asking to be allowed to do */
export interface PermissionScope {
  key: string;
  /** Like "Edit frames" */
  label: string;
  /** The quiet line under it, like "Only on a new page" */
  detail?: string;
  /** A warning tag after it, like "Risky" */
  risk?: string;
  /** What the risk tag reveals on hover, like "Checkout, Marketing site, Email kit and Docs use this library" */
  riskDetail?: string;
}

export type PermissionStatus = 'asking' | 'allowed' | 'declined';

export interface PermissionGateProps {
  /** The question, like "Allow the agent to edit Figma?" */
  title: ReactNode;
  /** Why it asks */
  subtitle?: ReactNode;
  /** Shown in the tile beside the question. Defaults to a shield */
  icon?: ReactNode;
  scopes: PermissionScope[];
  /** Keys of the ticked scopes. Leave it out to let the checkboxes hold their own */
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (keys: string[]) => void;
  /** How long the permission lasts, picked from a small dropdown in the footer. Defaults to This task, Today and Always */
  durations?: string[];
  /** The quiet line under each duration in its menu, by duration, like { Today: 'Until midnight' } */
  durationDetails?: Record<string, string>;
  duration?: string;
  defaultDuration?: string;
  onDurationChange?: (duration: string) => void;
  /** asking, allowed or declined. Leave it out to let the buttons move it */
  status?: PermissionStatus;
  defaultStatus?: PermissionStatus;
  onStatusChange?: (status: PermissionStatus) => void;
  /** Called with the ticked scopes and the duration. Return a promise and the button spins until it settles */
  onAllow?: (keys: string[], duration: string) => void | Promise<void>;
  onDecline?: () => void;
  /** Called by Revoke, after allowing */
  onRevoke?: () => void;
  /** Called by Undo, after declining */
  onUndo?: () => void;
  /** The line under "Allowed …", like "Applying the pricing fixes now". Crossfades when it changes */
  allowedDetail?: string;
  /** Replaces "Allowed 2 scopes for this task", like "Done. 6 frames edited". Crossfades when it changes */
  allowedTitle?: string;
  /** The agent is still working under the permission: a spinner instead of the green check, on the same neutral row */
  working?: boolean;
  /** A follow-up ask in the middle of a run, for one more scope. A single scope shows as a row led by a tile (nothing to
   *  tick) with a plain Allow; the icon tile stays neutral, and the scope's risk tag carries the warning */
  followUp?: boolean;
  /** The decline button. Defaults to "Not now"; a follow-up ask might say "Skip this frame" */
  declineLabel?: string;
  /** Shown after Not now */
  declinedTitle?: ReactNode;
  declinedDetail?: ReactNode;
  /** Clean only: the line in the foot strip after Not now. Defaults to "Nothing allowed" */
  declinedSummary?: string;
  /** Draws its own container (the default, as on designme.dev). Set true to sit it flat in a chat thread */
  bare?: boolean;
  className?: string;
}

const DURATIONS = ['This task', 'Today', 'Always'];
const DETAILS: Record<string, string> = { 'This task': 'Until the task is done', Today: 'Until midnight', Always: 'Until you revoke it' };
// "For this task" in the menu and "for this task" after Allowed; Always reads as it is
const durLabel = (d: string) => /^always$/i.test(d) ? d : 'For ' + d.toLowerCase();
const durSpan = (d: string) => /^always$/i.test(d) ? 'always' : 'for ' + d.toLowerCase();
const word = (n: number) => n > 1 ? 'scopes' : 'scope';

/** Clean's Allow: the number sits in a window of its own and a new count rolls in, up as a box is ticked, down as one clears */
function Count({ n }: { n: number }) {
  const reduce = useReducedMotion();
  const [items, setItems] = useState([{ n, cls: '', key: 0 }]);
  const last = useRef(n);
  useEffect(() => {
    const was = last.current; if (n === was) return; last.current = n;
    const up = n > was;
    setItems(it => [{ ...it[it.length - 1], cls: up ? 'dm-ou' : 'dm-od' }, { n, cls: up ? 'dm-iu' : 'dm-id', key: it[it.length - 1].key + 1 }]);
    const t = setTimeout(() => setItems(it => it.slice(-1)), reduce ? 0 : 300);
    return () => clearTimeout(t);
  }, [n, reduce]);
  return <span className="dm-pgx-cnt">{items.map(i => <i key={i.key} className={i.cls || undefined}>{i.n}</i>)}</span>;
}

/** The agent asks before it acts: pick the scopes and how long they last, then allow or decline. */
export function PermissionGate({
  title, subtitle, icon, scopes, value, defaultValue = [], onValueChange, durations = DURATIONS, durationDetails = DETAILS, duration, defaultDuration, onDurationChange,
  status, defaultStatus = 'asking', onStatusChange, onAllow, onDecline, onRevoke, onUndo, allowedDetail, allowedTitle, working = false, followUp = false,
  declineLabel = 'Not now', declinedTitle = 'The agent will skip these changes', declinedDetail, declinedSummary = 'Nothing allowed', bare = false, className
}: PermissionGateProps) {
  const [ticked, setTicked] = useControllable(value, defaultValue, onValueChange);
  const [dur, setDur] = useControllable(duration, defaultDuration ?? durations[0], onDurationChange);
  const durMenu = usePopover();
  const [state, setState] = useControllable(status, defaultStatus, onStatusChange);
  const [waiting, setWaiting] = useState(false);
  // a revoked permission fades out before the scopes come back
  const [leaving, setLeaving] = useState(false);
  // the scopes play their entrance when they come back, not when the card first appears
  const [back, setBack] = useState(0);
  const [granted, setGranted] = useState(0);
  // the names of the scopes allowed, for Clean's summary line in the foot strip
  const [names, setNames] = useState<string[]>([]);
  // the gate never keeps a height, in any style (owner, 17 and 18 Nov): it grows and shrinks with what it holds, eased, as
  // grow() does on the site
  const root = useRef<HTMLDivElement>(null), inner = useRef<HTMLDivElement>(null);
  const [clean, setClean] = useState(false);
  useIsoLayoutEffect(() => { setClean(root.current?.closest('[data-style]')?.getAttribute('data-style') === 'clean'); }, []);
  useIsoLayoutEffect(() => {
    const el = root.current, w = inner.current;
    if (!el || !w || typeof ResizeObserver === 'undefined') return;
    let first = true;
    const box = () => { const cs = getComputedStyle(el); return parseFloat(cs.paddingTop) + parseFloat(cs.paddingBottom) + parseFloat(cs.borderTopWidth) + parseFloat(cs.borderBottomWidth); };
    const fit = () => {
      const h = Math.ceil(w.getBoundingClientRect().height + box());
      if (first) { el.style.transition = 'none'; el.style.height = h + 'px'; void el.offsetHeight; el.style.transition = ''; first = false; }
      else el.style.height = h + 'px';
    };
    const ro = new ResizeObserver(fit); ro.observe(w); fit();
    return () => { ro.disconnect(); el.style.height = ''; };
  }, []);
  // Clean: the scopes fade up and out before the card eases to the result row's height
  const [fading, setFading] = useState(false);
  // asking again for one scope: nothing to tick, so the scope is a row led by a tile like the question's, and the button
  // just says Allow (every style)
  const single = followUp && state === 'asking' && scopes.length === 1;
  const keys = single ? [scopes[0].key] : ticked;
  const n = keys.length;

  useEffect(() => {
    if (!leaving) return;
    const t = setTimeout(() => { setLeaving(false); setState('asking'); setBack(b => b + 1); onRevoke?.(); }, 300);
    return () => clearTimeout(t);
  }, [leaving]); // eslint-disable-line react-hooks/exhaustive-deps

  const toggle = (key: string) => setTicked(ticked.includes(key) ? ticked.filter(k => k !== key) : scopes.map(s => s.key).filter(k => k === key || ticked.includes(k)));
  const allow = async () => {
    if (!n || waiting) return;
    setWaiting(true); setGranted(n); const picked = scopes.filter(s => keys.includes(s.key)).map(s => s.label); setNames(was => followUp ? [...was, ...picked] : picked);
    try { await onAllow?.(keys, dur); } finally { setWaiting(false); }
    if (clean) { setFading(true); await new Promise(r => setTimeout(r, 180)); setFading(false); }
    setState('allowed');
  };
  const decline = () => { setState('declined'); onDecline?.(); };
  const undo = () => { setState('asking'); setBack(b => b + 1); onUndo?.(); };
  const again = (i: number, ms = i * 50) => (back ? { className: 'dm-enter', style: enter(ms).style, key: back } : { className: undefined, style: undefined, key: 0 });
  // (in Clean the foot strip fades in once the card has grown to hold it, so no button shows cut off by the card's edge)
  const foot = again(1, clean ? 400 : 50);

  const allowLabel = n ? `Allow ${n} ${word(n)}` : 'Pick a scope';

  return (
    <div data-dm="" ref={root} className={cx('dm-pgx', !bare && 'dm-panel', 'dm-growing', followUp && state === 'asking' && 'dm-esc', className)}>
      {/* grow()'s wrapper in Clean; elsewhere it takes no box of its own */}
      <div ref={inner} className="dm-grow dm-dm-grow">
      <div className="dm-pgx-h">
        <span className="dm-pgx-ic">{icon ?? <Icon name="shield" />}</span>
        <div className="dm-pgx-ht"><b>{title}</b>{subtitle && <span className="dm-muted">{subtitle}</span>}</div>
      </div>
      {state === 'asking' && (
        <>
          <div key={'sc' + again(0).key} className={cx('dm-pgx-sc', again(0).className, fading && 'dm-leave')} style={again(0).style}>
            {scopes.map(s => {
              const risk = s.risk && (s.riskDetail ? <Tip label={s.riskDetail}><span className="dm-tag dm-warn">{s.risk}</span></Tip> : <span className="dm-tag dm-warn">{s.risk}</span>);
              const words = <span className="dm-t">{s.label}{s.detail && <span className="dm-d">{s.detail}</span>}</span>;
              return single
                ? <div key={s.key} className="dm-pgx-o dm-one"><span className="dm-oi"><Icon name="upload" /></span>{words}{risk}</div>
                : <label key={s.key} className="dm-pgx-o">
                    <input type="checkbox" checked={ticked.includes(s.key)} onChange={() => toggle(s.key)} />
                    <span className="dm-bx"><Icon name="check" size="xs" /></span>
                    {words}{risk}
                  </label>;
            })}
          </div>
          <div key={'f' + foot.key} className={cx('dm-pgx-f', foot.className)} style={foot.style}>
            <button {...durMenu.trigger} type="button" className="dm-pgx-db" aria-label="How long"><Swap className="dm-pgx-dv">{durLabel(dur)}</Swap><Icon name="chev-d" size="xs" /></button>
            <span className="dm-sp" />
            <button type="button" className="dm-pill dm-ghost dm-sm dm-pgx-no" onClick={decline}>{declineLabel}</button>
            <button type="button" className="dm-pill dm-primary dm-sm dm-pgx-ok" disabled={!n} onClick={allow}>
              {waiting ? <Spin /> : single ? <Swap>Allow</Swap> : clean && n
                ? <span className="dm-pgx-l">Allow <Count n={n} /> <Swap className="dm-pgx-w">{word(n)}</Swap></span>
                : <Swap>{allowLabel}</Swap>}
            </button>
          </div>
        </>
      )}
      <div {...durMenu.pop} className={cx(durMenu.pop.className, 'dm-pgx-pop')} role="menu" aria-label="How long">
        {durations.map(d => (
          <button key={d} type="button" className="dm-mi" role="menuitemradio" aria-checked={d === dur} onClick={() => { setDur(d); durMenu.closeSoon(); }}>
            <span>{durLabel(d)}{durationDetails[d] && <span className="dm-d">{durationDetails[d]}</span>}</span><span className="dm-ck"><Icon name="check" size="xs" /></span>
          </button>
        ))}
      </div>
      {state === 'allowed' && (
        <div className={cx('dm-pgx-done', working ? 'dm-run' : 'dm-ok', leaving ? 'dm-leave' : 'dm-enter')}>
          <span className="dm-g">{working ? <Spin /> : <Icon name={clean ? 'check' : 'ok'} />}</span>
          <span className="dm-t">
            <b className="dm-pgx-a"><Swap>{allowedTitle ?? `Allowed ${granted || n} ${(granted || n) > 1 ? 'scopes' : 'scope'} ${durSpan(dur)}`}</Swap></b>
            {allowedDetail !== undefined && <Swap>{allowedDetail}</Swap>}
          </span>
          <button type="button" className="dm-pill dm-line dm-sm" onClick={() => setLeaving(true)}>Revoke</button>
          <span className="dm-pgx-sum"><span className="dm-l">{names.join(', ')}</span><span className="dm-s">{`${names.length} ${word(names.length)} allowed`}</span></span>
        </div>
      )}
      {state === 'declined' && (
        <div className="dm-pgx-done dm-enter" style={{ background: 'var(--dm-chip)' }}>
          <Icon name="info" />
          <span className="dm-t">{declinedTitle}{declinedDetail && <span>{declinedDetail}</span>}</span>
          <button type="button" className="dm-pill dm-line dm-sm" onClick={undo}>Undo</button>
          <span className="dm-pgx-sum"><span className="dm-l">{declinedSummary}</span><span className="dm-s">{declinedSummary}</span></span>
        </div>
      )}
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Permission gate ---------- */
/* the agent asks in the chat as one card: the question, the scopes to tick, and a footer with how long and the two
   answers. Without .panel it sits flat in the thread */
.dm-pgx{position:relative;width:100%;max-width:400px;margin:0 auto;padding:var(--dm-s-1) 0;display:flex;flex-direction:column;gap:var(--dm-s-3)}
.dm-pgx.dm-panel{padding:var(--dm-s-4)}
.dm-pgx-h{display:flex;gap:var(--dm-s-3);align-items:center}
.dm-pgx-ic{width:32px;height:32px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-chip);display:grid;place-items:center;flex:none}
.dm-pgx-ht{display:flex;flex-direction:column;min-width:0}
.dm-pgx-ht b{font-weight:500;font-size:14px}
.dm-pgx-ht span{font-size:13px}
/* the scopes line up with the head (owner, 18 Nov): each box centred in a 32px column under the icon tile, its words where the
   question's start, and the row's hover fill exactly the content's width, from the tile's left edge to the right edge the
   buttons below end on. The box sits 7px inside the fill, and a tag at the row's end sits 7px inside it too */
.dm-pgx-sc{display:flex;flex-direction:column}
.dm-pgx-o{display:grid;grid-template-columns:32px minmax(0,1fr) auto;align-items:center;column-gap:var(--dm-s-3);padding:var(--dm-s-2) 7px var(--dm-s-2) 0;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));cursor:pointer;font-size:13.5px;transition:background .25s}
.dm-pgx-o>.dm-bx{justify-self:center}
@media (hover:hover) and (pointer:fine){.dm-pgx-o:hover{background:var(--dm-row)}}
.dm-pgx-o input{position:absolute;opacity:0;pointer-events:none}
.dm-pgx-o .dm-bx{width:18px;height:18px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));box-shadow:inset 0 0 0 1.5px var(--dm-fg2);display:grid;place-items:center;color:transparent;flex:none;transition:background .3s var(--dm-ease),box-shadow .3s,color .3s}
.dm-pgx-o .dm-bx svg{transform:scale(.4);transition:transform .35s var(--dm-ease)}
.dm-pgx-o input:checked+.dm-bx{background:var(--dm-accent);box-shadow:inset 0 0 0 1.5px var(--dm-accent-mark,var(--dm-accent));color:var(--dm-on-accent)}
.dm-pgx-o input:checked+.dm-bx svg{transform:none}
.dm-pgx-o input:focus-visible+.dm-bx{outline:2px solid var(--dm-focus);outline-offset:2px}
.dm-pgx-o .dm-t{flex:1;min-width:0}
/* asking again for one scope, every style: nothing to tick, so the scope is a plain row led by a tile like the question's
   (what it does, in the same 32px column) and the button just says Allow (owner, 18 Nov) */
.dm-pgx-o.dm-one{cursor:default}
@media (hover:hover) and (pointer:fine){.dm-pgx-o.dm-one:hover{background:none}}
.dm-pgx-o.dm-one>.dm-oi{width:32px;height:32px;display:grid;place-items:center;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-chip);color:var(--dm-fg2)}
:root[data-style="clean"] .dm-pgx-o.dm-one>.dm-oi,:root [data-style="clean"] .dm-pgx-o.dm-one>.dm-oi,:root [data-style="clean"].dm-pgx-o.dm-one>.dm-oi{box-shadow:inset 0 0 0 1px var(--dm-hair)}
.dm-pgx-o .dm-d{display:block;font-size:12px;color:var(--dm-muted)}
.dm-pgx-f{display:flex;align-items:center;gap:6px;padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-pgx-f .dm-sp{flex:1}
/* on a narrow stage the duration gets its own row, and the two buttons stay together under it on the right */
@container (max-width:340px){.dm-pgx-f{flex-wrap:wrap;padding-top:var(--dm-s-3)}.dm-pgx-f .dm-sp{flex-basis:100%}.dm-pgx-no{margin:var(--dm-s-2) 0 0 auto}.dm-pgx-ok{margin-top:var(--dm-s-2)}}
/* how long: a small dropdown, the way a menu of choices usually looks */
.dm-pgx-db{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 var(--dm-s-2) 0 10px;margin-left:0;border-radius:var(--dm-r-pill);font-size:13px;color:var(--dm-fg2);white-space:nowrap;transition:background .16s,color .16s}
.dm-pgx-db[aria-expanded="true"]{background:var(--dm-row);color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.dm-pgx-db:hover{background:var(--dm-row);color:var(--dm-fg)}}
.dm-pgx-db>svg{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.dm-pgx-db[aria-expanded="true"]>svg{transform:rotate(180deg)}
.dm-pgx-pop{min-width:230px}
.dm-pgx-ok[disabled]{opacity:1;cursor:not-allowed;background:var(--dm-dis-hatch),var(--dm-dis-fill);color:var(--dm-dis);box-shadow:var(--dm-soft-ring)}
.dm-pgx-done{display:flex;align-items:center;gap:var(--dm-s-3);padding:10px 7px 10px 0;border-radius:var(--dm-r-in);background:var(--dm-chip);font-size:13.5px}
/* its mark sits centred in the scopes' 32px column, under the head's tile, and its words start on the title's column */
.dm-pgx-done>svg{margin-inline:8px}
/* on a phone the answered row wraps to a small card: its words and its button 16px from its top, bottom and right; its mark
   stays centred under the head's tile */
@container (max-width:340px){.dm-pgx-done{padding:var(--dm-s-4) var(--dm-s-4) var(--dm-s-4) 0}}
/* its button is a white pill on the grey row */
.dm-pgx-done .dm-pill{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-on-tint-btn)}
@media (hover:hover) and (pointer:fine){.dm-pgx-done .dm-pill:hover{background:var(--dm-surface);box-shadow:var(--dm-on-tint-btn-h)}}
.dm-pgx-done .dm-t{flex:1;color:var(--dm-fg)}
.dm-pgx-done .dm-t span{display:block;font-size:12px;color:var(--dm-fg2)}
.dm-pgx-done>svg{color:var(--dm-ok)}
/* while the agent works under the permission: a neutral row with a spinner and a live line. Once done the spinner becomes the
   green tick and the row stays neutral: no green fill and no clock (owner, 18 Nov) */
.dm-pgx-done .dm-g{width:32px;height:18px;display:grid;place-items:center;flex:none;color:var(--dm-fg2)}
.dm-pgx-done.dm-ok .dm-g{color:var(--dm-ok)}
.dm-pgx-done .dm-t b{display:block;font-weight:400}
/* asking again mid-run, for one more scope: the tile turns amber */
.dm-pgx-ic{transition:background .32s var(--dm-ease)}
/* asking again keeps the tile neutral in every style: the Risky tag on the scope carries the warning (owner, 18 Nov) */
.dm-pgx-scope{display:flex;flex-direction:column;gap:var(--dm-s-3)}
/* the line in the foot strip once you have answered (Clean only): the scopes you allowed, or that you allowed none */
.dm-pgx-sum{display:none}

/* Clean (owner, 18 Nov): a card with the question, the scopes and an off-white foot strip. Its content sits 16px from
   every edge; the controls in the strip sit 16px from the card's sides and bottom and from the strip's hairline (owner,
   23 Nov), and the duration select lines up with the content above by its text, not its hover box. The ticks are
   ink and draw in, the count on Allow rolls as boxes are ticked, and once you answer the scopes fold into one summary line
   in the strip while the card eases to its new height (grow(), centred in its stage). Its height is never kept */
/* the card clips its strips to its round corners; the duration menu opens out of it (nothing changes height while it is open) */
:root[data-style="clean"] .dm-pgx.dm-panel,:root [data-style="clean"] .dm-pgx.dm-panel,:root [data-style="clean"].dm-pgx.dm-panel{padding:16px 16px 0;overflow:clip;overflow-clip-margin:0px}
:root[data-style="clean"] .dm-pgx.dm-panel:has(.dm-pgx-pop.dm-open),:root [data-style="clean"] .dm-pgx.dm-panel:has(.dm-pgx-pop.dm-open),:root [data-style="clean"].dm-pgx.dm-panel:has(.dm-pgx-pop.dm-open){overflow:visible}
:root[data-style="clean"] .dm-pgx-ic,:root [data-style="clean"] .dm-pgx-ic,:root [data-style="clean"].dm-pgx-ic{box-shadow:inset 0 0 0 1px var(--dm-hair)}
/* asking again keeps the tile neutral: the Risky tag on the scope carries the warning */
:root[data-style="clean"] .dm-pgx-ht b,:root [data-style="clean"] .dm-pgx-ht b,:root [data-style="clean"].dm-pgx-ht b{line-height:20px;letter-spacing:-.01em}
:root[data-style="clean"] .dm-pgx-ht span,:root [data-style="clean"] .dm-pgx-ht span,:root [data-style="clean"].dm-pgx-ht span,:root[data-style="clean"] .dm-pgx-o .dm-d,:root [data-style="clean"] .dm-pgx-o .dm-d,:root [data-style="clean"].dm-pgx-o .dm-d,:root[data-style="clean"] .dm-pgx-done .dm-t span,:root [data-style="clean"] .dm-pgx-done .dm-t span,:root [data-style="clean"].dm-pgx-done .dm-t span{line-height:18px}
:root[data-style="clean"] :is(.dm-pgx-o,.dm-pgx-done) .dm-t,:root [data-style="clean"] :is(.dm-pgx-o,.dm-pgx-done) .dm-t,:root [data-style="clean"]:is(.dm-pgx-o,.dm-pgx-done) .dm-t{line-height:20px}
/* a scope row: its box in a 32px column under the question's tile, centred, so its words start where the question's do;
   hairlines between rows, which give way to the quiet fill of the row under the pointer */
:root[data-style="clean"] .dm-pgx-o,:root [data-style="clean"] .dm-pgx-o,:root [data-style="clean"].dm-pgx-o{position:relative;display:grid;grid-template-columns:32px minmax(0,1fr) auto;column-gap:12px;transition:background-color var(--dm-t-fast) var(--dm-ease)}
